/* ─── Status badge HTML ─────────────────────────────────────────────────── */
export function badge(status) {
  const labels = {
    running:  'Running',
    stopped:  'Stopped',
    deploying:'Deploying...',
    error:    'Error',
    starting: 'Starting…',
    stopping: 'Stopping…',
    restarting:'Restarting…',
    pending:   'Pending…',
  };
  return `<span class="badge badge-${status}">${labels[status] || 'Unknown'}</span>`;
}

/* ─── Toast notifications ───────────────────────────────────────────────── */
export function toast(msg, type = 'success') {
  const el = document.createElement('div');
  el.className = `toast ${type}`;
  el.textContent = msg;
  document.getElementById('toast-container').appendChild(el);
  setTimeout(() => el.remove(), 3200);
}

/* ─── Confirm dialog ────────────────────────────────────────────────────── */
export function confirm(title, body) {
  return new Promise(resolve => {
    const backdrop = document.createElement('div');
    backdrop.className = 'dialog-backdrop';
    backdrop.innerHTML = `
      <div class="dialog">
        <div class="dialog-title">${title}</div>
        <div class="dialog-body" style="color:var(--text-secondary);font-size:13px;line-height:1.5">${body}</div>
        <div class="dialog-actions">
          <button class="btn btn-secondary" id="dlg-cancel">Cancel</button>
          <button class="btn btn-danger" id="dlg-ok">Confirm</button>
        </div>
      </div>`;
    document.body.appendChild(backdrop);
    backdrop.querySelector('#dlg-cancel').onclick = () => { backdrop.remove(); resolve(false); };
    backdrop.querySelector('#dlg-ok').onclick    = () => { backdrop.remove(); resolve(true); };
    backdrop.addEventListener('click', e => { if (e.target === backdrop) { backdrop.remove(); resolve(false); } });
  });
}

export function prompt(title, label, initialValue = '') {
  return new Promise(resolve => {
    const backdrop = document.createElement('div');
    backdrop.className = 'dialog-backdrop';
    backdrop.innerHTML = `
      <div class="dialog">
        <div class="dialog-title">${title}</div>
        <div class="dialog-body">
          <div style="font-size:12px;color:var(--text-muted);margin-bottom:8px">${label}</div>
          <input type="text" class="input" id="prompt-input" style="width:100%" value="${initialValue}" autofocus />
        </div>
        <div class="dialog-actions">
          <button class="btn btn-secondary" id="prompt-cancel">Cancel</button>
          <button class="btn btn-primary" id="prompt-ok">Save Changes</button>
        </div>
      </div>`;
    document.body.appendChild(backdrop);
    const input = backdrop.querySelector('#prompt-input');
    input.focus();
    input.select();
    
    const finish = (val) => { backdrop.remove(); resolve(val); };
    backdrop.querySelector('#prompt-cancel').onclick = () => finish(null);
    backdrop.querySelector('#prompt-ok').onclick = () => finish(input.value.trim());
    input.onkeydown = (e) => {
      if (e.key === 'Enter') finish(input.value.trim());
      if (e.key === 'Escape') finish(null);
    };
    backdrop.addEventListener('click', e => { if (e.target === backdrop) finish(null); });
  });
}

/* ─── Spinner HTML ──────────────────────────────────────────────────────── */
export const spinner = `<span class="spinner"></span>`;

/* ─── .env import ───────────────────────────────────────────────────────── */

/**
 * Parse .env file text into an ordered { KEY: value } object.
 * Supports comments, blank lines, `export KEY=...`, single/double quotes
 * (double quotes understand \n, \t, \" and may span lines) and trailing
 * ` # comments` on unquoted values. Invalid lines are skipped.
 */
export function parseDotEnv(text) {
  const out = {};
  const lines = String(text || '').replace(/^﻿/, '').split(/\r?\n/);
  for (let i = 0; i < lines.length; i++) {
    const m = lines[i].match(/^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_.-]*)\s*=\s*(.*)$/);
    if (!m) continue;
    const key = m[1];
    let raw = m[2];

    if (raw.startsWith('"')) {
      // Collect until the closing unescaped quote, possibly over several lines
      let body = raw.slice(1);
      let close = _closingQuote(body);
      while (close < 0 && i + 1 < lines.length) {
        body += '\n' + lines[++i];
        close = _closingQuote(body);
      }
      if (close >= 0) body = body.slice(0, close);
      out[key] = body.replace(/\\(.)/g, (_, c) => (c === 'n' ? '\n' : c === 't' ? '\t' : c));
    } else if (raw.startsWith("'")) {
      const close = raw.indexOf("'", 1);
      out[key] = close < 0 ? raw.slice(1) : raw.slice(1, close);
    } else {
      out[key] = raw.replace(/\s+#.*$/, '').trim();
    }
  }
  return out;
}

function _closingQuote(s) {
  for (let j = 0; j < s.length; j++) {
    if (s[j] === '\\') { j++; continue; }
    if (s[j] === '"') return j;
  }
  return -1;
}

/** Let the user pick a local text file; resolves with its contents, or null when cancelled. */
export function pickTextFile(accept = '') {
  return new Promise(resolve => {
    const input = document.createElement('input');
    input.type = 'file';
    if (accept) input.accept = accept;
    input.style.display = 'none';
    input.addEventListener('change', async () => {
      const file = input.files?.[0];
      input.remove();
      resolve(file ? await file.text() : null);
    });
    input.addEventListener('cancel', () => { input.remove(); resolve(null); });
    document.body.appendChild(input);
    input.click();
  });
}

/**
 * Merge parsed env vars into a list of `.env-row` elements: existing keys get
 * the new value, unknown keys get a new row via addRow(key, value).
 * Returns { added, updated }.
 */
export function mergeEnvIntoRows(container, vars, addRow) {
  const byKey = new Map();
  container.querySelectorAll('.env-row').forEach(row => {
    const k = row.querySelector('[data-env-key]')?.value.trim();
    if (k) byKey.set(k, row);
  });
  // Reuse a trailing blank row (e.g. the default empty one) before adding new rows
  const blank = [...container.querySelectorAll('.env-row')].find(row =>
    !row.querySelector('[data-env-key]')?.value.trim() && !row.querySelector('[data-env-val]')?.value);
  let added = 0, updated = 0, blankUsed = false;
  for (const [k, v] of Object.entries(vars)) {
    const row = byKey.get(k);
    if (row) {
      row.querySelector('[data-env-val]').value = v;
      updated++;
    } else if (blank && !blankUsed) {
      blank.querySelector('[data-env-key]').value = k;
      blank.querySelector('[data-env-val]').value = v;
      blankUsed = true;
      added++;
    } else {
      addRow(k, v);
      added++;
    }
  }
  return { added, updated };
}

/* ─── Format helpers ────────────────────────────────────────────────────── */
export function fmtUptime(secs) {
  const d = Math.floor(secs / 86400);
  if (d > 0) return `${d}d ${Math.floor((secs % 86400) / 3600)}h`;
  const h = Math.floor(secs / 3600);
  const m = Math.floor((secs % 3600) / 60);
  const s = secs % 60;
  if (h > 0) return `${h}h ${m}m`;
  if (m > 0) return `${m}m ${s}s`;
  return `${s}s`;
}

export function fmtSize(bytes) {
  if (!bytes) return '';
  if (bytes < 1024) return `${bytes}B`;
  if (bytes < 1048576) return `${(bytes / 1024).toFixed(0)}KB`;
  return `${(bytes / 1048576).toFixed(1)}MB`;
}

export function fmtDate(iso) {
  if (!iso) return '—';
  return new Date(iso).toLocaleString();
}

export function timeAgo(iso) {
  if (!iso) return 'never';
  // Ensure UTC parsing — append Z if no timezone info present
  const normalized = /[Z+\-]\d*$/.test(iso.trim()) ? iso : iso + 'Z';
  const secs = Math.floor((Date.now() - new Date(normalized).getTime()) / 1000);
  if (secs < 5)  return 'just now';
  if (secs < 60) return `${secs}s ago`;
  const mins = Math.floor(secs / 60);
  if (mins < 60) return `${mins}m ago`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24)  return `${hrs}h ago`;
  const days = Math.floor(hrs / 24);
  return `${days}d ago`;
}

/* ─── Log line colorizer ─────────────────────────────────────────────────── */
export function logClass(line) {
  if (/error|fail|fatal|exception/i.test(line)) return 'log-error';
  if (/warn/i.test(line)) return 'log-warn';
  if (/success|ready|started|listening|connected/i.test(line)) return 'log-success';
  if (/info|debug/i.test(line)) return 'log-info';
  return 'log-default';
}

/* ─── setBtn helper ─────────────────────────────────────────────────────── */
export function setBtn(btn, loading, label, iconHtml) {
  if (loading) {
    btn.disabled = true;
    btn.innerHTML = `${spinner} ${label}`;
  } else {
    btn.disabled = false;
    btn.innerHTML = `${iconHtml} ${label}`;
  }
}

/* ─── Design tokens from CSS ────────────────────────────────────────────── */
/** Current value of a CSS custom property, e.g. cssVar('--accent') → '#8e9bff'. */
export function cssVar(name) {
  return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
}

/* ─── Audit log table (app Activity tab + Audit log page) ───────────────── */
const AUDIT_TONE = {
  'app.start': 'var(--green)', 'app.stop': 'var(--red)', 'app.restart': 'var(--yellow)',
  'app.deploy': 'var(--accent)', 'app.pull': 'var(--accent)', 'app.rebuild': 'var(--accent)',
  'app.zero_downtime_deploy': 'var(--green)', 'app.rolling_deploy': 'var(--green)',
  'app.delete': 'var(--red)', 'auth.change_password': 'var(--yellow)',
  'user.create': 'var(--green)', 'user.delete': 'var(--red)',
  'node.connect': 'var(--green)', 'node.enable': 'var(--green)', 'node.disable': 'var(--yellow)', 'node.delete': 'var(--red)',
};

function _escAudit(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

/** Render audit entries as a .table; showApp adds the app name column. */
export function auditTableHTML(entries, { showApp = false } = {}) {
  const rows = entries.map(e => {
    const tone = AUDIT_TONE[e.action] || 'var(--faint)';
    const detail = e.detail
      ? Object.entries(e.detail).filter(([k]) => k !== 'name').map(([k, v]) => `${k}: ${typeof v === 'object' ? JSON.stringify(v) : v}`).join(' · ')
      : '';
    const when = new Date(e.timestamp);
    return `<tr>
      <td class="audit-time" title="${_escAudit(when.toLocaleString())}">${_escAudit(when.toLocaleString([], { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }))}</td>
      <td><span class="audit-action"><span class="dot" style="background:${tone}"></span>${_escAudit(e.action)}</span></td>
      ${showApp ? `<td class="cell-muted">${_escAudit(e.detail?.name || '')}</td>` : ''}
      <td class="audit-detail" title="${_escAudit(detail)}">${_escAudit(detail)}</td>
      <td class="cell-mono">${_escAudit(e.actor || '')}</td>
    </tr>`;
  }).join('');
  return `<div class="audit-table-wrap"><table class="table audit-table">
    <thead><tr><th>Time</th><th>Action</th>${showApp ? '<th>App</th>' : ''}<th>Detail</th><th>User</th></tr></thead>
    <tbody>${rows}</tbody>
  </table></div>`;
}
